/* ============ the half of the manual that is written in pencil ==========
   doctrine() above is what this army knows before the first shot is fired:
   a value per credit per role, derived from the weapon tables, cached on
   faction and era, identical in every match. It is the right thing to open
   on and the wrong thing to close on, because it cannot know THIS opponent,
   THIS ground, or that the road the wave keeps using is covered by four
   anti-tank guns. Six records in this file remember pain - graves, alarms,
   mineSigns, raidHeat, siegeNeed, aimShy - and not one remembers payment.
   With no value attached to a choice there is nothing a second choice can
   beat, which is why the same plot yields the same wave for twenty minutes.

   This is the other half. ONE book, THREE postures, one choice a wave:

     armour   the wave is hulls.  More tanks, fewer tubes, fewer bodies.
     gunline  the wave is tubes.  Howitzers, rockets and spotters; fewer hulls.
     swarm    the wave is bodies. Rifles and missile teams, and many of them.

   THREE, and the number is arithmetic rather than taste. A match at Veteran
   launches six to eight waves and at Elite eight to eleven. Ten arms over
   that horizon is one pull an arm: the commander would end the battle
   knowing nothing and looking random, which is variety, not intelligence.
   Three arms get two to six pulls each - enough to abandon a posture that is
   plainly failing, which is honestly the whole of what one match can teach,
   and it is said out loud here rather than promised in a comment.

   WHAT MAKES A POSTURE REAL. counterMix() answers "what does the picture
   demand"; a posture answers "and which of those answers has been paying".
   It bites in two places, because one is not enough. It reweights the roles
   counterMix already asked for - never invents one, see stanceMix - and it
   moves the INFANTRY-TO-VEHICLE SPLIT, which nothing in this file has ever
   been able to move: buildToward() normalises inside a category and the two
   call sites fire independently, so a multiplier on rifles cannot buy one
   more rifleman relative to one more tank. The split gate is what makes
   three postures three different armies instead of three shuffles of one.

   DIFFICULTY runs through one gate and one multiplier, as everything else
   here does. learnOn() is read >= 0.55, the same threshold beginSiege
   already uses to decide a commander reads ground well enough to stand off
   and shell it. A Recruit and a Regular never open an episode, never choose
   a posture and never lean a queue: armNow stays null, stanceMix hands back
   counterMix's object untouched and stanceSplit returns -1, which is this
   file's present behaviour to the byte - including every one of the 89
   behaviour checks, which run their commander at Regular. Above the gate
   every lever is scaled by grip = D.read, exactly as counterMix,
   pickApproach and buildToward already scale theirs.                     */
const STANCE = {
  /* Multipliers on counterMix's OUTPUT, and a target infantry share of the
     ground army. Both are scaled by grip, so a 1.90 arrives as 1.54 at
     Veteran and 1.72 at Elite. The largest is 2.10 because a posture that
     moves the queue by less than one unit a wave is a posture nobody can
     measure - three arms separated by 0.7 of a vehicle was the measured
     death of the previous attempt, not a theory about it. */
  armour:  { tech: 2, need: ["mbt"], split: 0.40,
             veh: { mbt: 1.90, heavy: 1.80, tankdestroyer: 1.25, lighttank: 1.15,
                    ifv: 1.10, spg: 0.55, mlrs: 0.55 },
             inf: { at: 1.15, rifle: 0.85, mortar: 0.60, sniper: 0.60 } },
  gunline: { tech: 2, need: ["spg"], split: 0.52,
             veh: { spg: 2.10, mlrs: 2.00, radarv: 1.30, mbt: 0.70, heavy: 0.70,
                    ifv: 0.70 },
             inf: { mortar: 1.70, sniper: 1.60, rifle: 0.90 } },
  swarm:   { tech: 0, need: ["rifle", "at"], split: 0.68,
             inf: { rifle: 1.50, at: 1.60, mg: 1.50, mortar: 1.20 },
             veh: { ifv: 1.20, mbt: 0.70, heavy: 0.60, spg: 0.80 } },
};
const ARMS = ["armour", "gunline", "swarm"];
const LEARN_READ = 0.55;   // the tier beginSiege already trusts to read ground
const N0 = 2;              // the manual is worth two pulls of experience...
const LMAX = 0.75;         // ...and never gives up more than three quarters
const NCAP = 8;            // the step floors at 1/8: eight waves re-shape a value
const EXPLORE = 0.12;      // UCB constant, before grip
const MIN_CRED = 0.34;     // the posture that set the stance keeps a third
const WAVE_MIN = 1800;     // below this a push is a probe and teaches nothing
const BASE_N = 6;          // the yardstick keeps tracking rather than freezing
let book = null;           // posture -> { n, q, p }
let armNow = null;         // the posture in force, or null when there is no choice
let ep = null, epN = 0;    // the open episode and its serial
let base = 0, baseN = 0;   // the running mean every push is scored against
let bookEra = null;        // the generation these priors were drawn for

function learnOn() { return !!book && (D.read || 0) >= LEARN_READ; }

/* ---- the prior, and it is doctrine() and nothing else ----
   doctrine() scores a role as this army's value per credit against a class
   over the share a typical army of the period puts there, so 1.00 means
   unremarkable. A posture's prior is the mean of the entries it spends its
   money on, CENTRED on the three arms so that it is a preference and not a
   level - the same reason the reward is centred, and for the same arithmetic.
   DOCT_SET deliberately carries no entry for spg, mlrs, sniper or radarv
   (see the note above it), so the manual has no opinion at all about tube
   artillery: gunline opens at the flat share and has to earn its place from
   evidence. That is the honest reading of a table that says nothing, and it
   is better than inventing an entry for it here. */
function armPrior() {
  const out = { armour: 0, gunline: 0, swarm: 0 };
  let dm = null;
  try { dm = doctrine(P.faction, P.era || CUR_ERA); } catch (e) { dm = null; }
  if (!dm || !dm.heavy || !dm.infantry) return out;
  const num = (v) => (typeof v === "number" && isFinite(v) ? v : 1);
  const raw = {
    armour:  (num(dm.heavy.mbt) + num(dm.heavy.heavy)) / 2,
    gunline: 1,
    swarm:   (num(dm.heavy.at) + num(dm.infantry.mg) + num(dm.infantry.rifle)) / 3,
  };
  let m = 0;
  for (const a of ARMS) m += raw[a];
  m /= ARMS.length;
  /* 0.6 sets the exchange rate between a doctrine edge and a measured one:
     the widest edge doctrine() can express is 0.55 against 1.80, which
     arrives here as a prior gap of 0.30 (clamped), and at the full learned
     weight of 0.75 an OBSERVED gap of 0.10 in exchange ratio is enough to
     overturn it. Early, when the learned weight is 0.25, it is not. That is
     "some flexibility in a reasonable way" written as two numbers. */
  for (const a of ARMS) out[a] = U.clamp((raw[a] - m) * 0.6, -0.30, 0.30);
  return out;
}

function bookInit() {
  const p = armPrior();
  book = {};
  /* n starts at one imaginary pull so the exploration term is finite and the
     learned weight starts at a quarter; q starts at zero because zero is
     what "no experience" means once the value being learned is an ADVANTAGE
     over our own average, not an absolute. */
  for (const a of ARMS) book[a] = { n: 1, q: 0, p: p[a] };
  bookEra = P.era || CUR_ERA;
  armNow = null; ep = null; epN = 0; base = 0; baseN = 0;
}

/* An era step re-equips the army - our own MBT goes from 690 credits to
   1,500 and its gun with it - so the manual is re-read and the pencil half
   erased. Not a reset: half of what was learned is about this opponent and
   this ground, and neither of those changed. */
function bookEraWatch() {
  const era = P.era || CUR_ERA;
  if (era === bookEra) return;
  bookEra = era;
  const p = armPrior();
  for (const a of ARMS) {
    const b = book[a];
    b.p = p[a]; b.q *= 0.5; b.n = Math.max(1, b.n * 0.5);
  }
}

/* A posture this army cannot field is struck off rather than explored: a
   wave spent discovering that the factory cannot cut a howitzer is not
   exploration, it is a wasted wave that writes a real negative against a
   choice that was never made. Tested against the roles the posture actually
   spends on, through unitFor - our own roster, ours to read. */
function armReady(a) {
  const s = STANCE[a];
  if (!s) return false;
  if (P.tech < (s.tech || 0)) return false;
  for (const role of s.need) if (!unitFor(P.faction, role, P.era)) return false;
  return true;
}

/* ---- the policy: UCB1 over a SHRUNK value ----
     score(a) = (1 - lam) * prior + lam * learned + C * sqrt(ln(1+T) / n)
   The bound on how far experience may carry this commander is a bound on the
   WEIGHT the experience carries, never on its VALUE, and that distinction is
   the whole redesign. A clamp on the value is what made every arm of the
   previous attempt identical: the reward carried a large offset common to
   all of them, every estimate ran into the same boundary, the argmax tied
   and the tie-break handed back the first arm in the list for twenty waves.
   A weight MULTIPLIES the gap between two estimates; it cannot close one.
   lam = 0.75*n/(n+2): a quarter of the decision at the first pull, half at
   two, two thirds at four, three quarters in the limit. The manual keeps a
   hand on the wheel for ever, which is exactly what was asked for.
   The exploration term needs no schedule: for the arm being pulled n grows
   with T so its bonus falls like sqrt(ln T / T) and the commander COMMITS;
   for an arm left alone n is fixed and the bonus creeps up like sqrt(ln T),
   so nothing is unreachable, but it creeps - 1.18 at T=3, 1.52 at T=10,
   1.75 at T=20 - far too slowly to unseat a posture that is paying. */
function chooseArm() {
  if (!learnOn()) { armNow = null; return; }
  let ready = 0;
  for (const a of ARMS) if (armReady(a)) ready++;
  /* no choice to make is not a choice: before the factory there is exactly
     one possible army and the loop stays out of the way entirely */
  if (ready < 2) { armNow = null; return; }
  const grip = D.read === undefined ? 1 : D.read;
  const C = EXPLORE * grip;
  let T = 0;
  for (const a of ARMS) T += book[a].n;
  let best = null, bs = -Infinity;
  for (const a of ARMS) {
    if (!armReady(a)) continue;
    const b = book[a];
    const lam = LMAX * b.n / (b.n + N0);
    const s = (1 - lam) * b.p + lam * b.q +
              C * Math.sqrt(Math.log(1 + T) / Math.max(0.5, b.n));
    if (s > bs) { bs = s; best = a; }
  }
  armNow = best;
}

/* counterMix() is NOT edited and NOT wrapped where any test reads it:
   intel().mix still calls it directly, so behaviour check [29] measures the
   identical function against the identical picture and prints the identical
   four numbers. This leans the object counterMix hands back - a fresh object
   built on every call - and only at the one call site that spends money. */
function stanceMix(a) {
  const mix = counterMix(a);
  const s = (learnOn() && armNow) ? STANCE[armNow] : null;
  if (!s) return mix;
  const grip = D.read === undefined ? 1 : D.read;
  for (const cat of ["inf", "veh"]) {
    const t = s[cat], o = mix[cat];
    if (!t || !o) continue;
    for (const role in t) {
      /* the hard bound, and it is one line: a posture REWEIGHTS what the
         picture already asked for and cannot put a role on the list that
         counterMix left off. No posture can answer a tank corps with mortars
         because the manual happened to like mortars. */
      if (o[role] === undefined) continue;
      o[role] *= 1 + (t[role] - 1) * grip;
    }
  }
  /* the same monoculture floor counterMix applies to its own answer, applied
     again to ours: a posture may lean a queue and may not empty it */
  const floor = (o, keys) => {
    let tot = 0, gp = 0;
    for (const k in o) tot += o[k];
    for (const k of keys) gp += o[k] || 0;
    if (tot <= 0 || gp >= tot * 0.35) return;
    const share = (tot * 0.35 - gp) / keys.length;
    for (const k of keys) if (o[k] !== undefined) o[k] += share;
  };
  floor(mix.inf, ["rifle"]);
  floor(mix.veh, P.tech >= 2 ? ["mbt", "ifv"] : ["ifv", "lighttank"]);
  return mix;
}

/* Which queue to hold, so a posture can change the SHAPE of the army and not
   merely its trim: -1 hold nothing, 0 hold the barracks, 1 hold the factory.
   A deadband of eight points because a controller without one oscillates,
   and never below five units because an army of three has no shape to hold.
   The caller releases a held queue the moment the preferred one buys
   nothing, so this is a preference and can never become a stall. */
function stanceSplit(army) {
  const s = (learnOn() && armNow) ? STANCE[armNow] : null;
  if (!s || army.length < 5) return -1;
  const grip = D.read === undefined ? 1 : D.read;
  const tgt = 0.55 + (s.split - 0.55) * grip;
  let nInf = 0;
  for (const u of army) if (u.def.cat === "infantry") nInf++;
  const share = nInf / army.length;
  if (share > tgt + 0.08) return 0;
  if (share < tgt - 0.08) return 1;
  return -1;
}

/* ---- the episode: one push, and what it was actually made of ----
   Opened and extended by bookWave(), which is already the one place a wave
   is committed - the ground launch and the landing that joins one - so an
   amphibious theatre is inside this loop instead of quietly outside it.
   Everything recorded about our own side is exact: our units, at what we
   paid, tagged with the posture in force when each of them joined the army. */
function learnCommit() {
  if (!learnOn()) return;
  if (!ep) { epN++; ep = { t: G.time, cost: 0, kills: 0, razed: 0, lost: 0,
                           arm: armNow, share: {}, r: 12 * CFG.TILE,
                           cx: P.homeX, cy: P.homeY }; }
  let reach = 0, n = 0, sx = 0, sy = 0;
  for (const u of attackWave) {
    if (u.dead) continue;
    sx += u.x; sy += u.y; n++;
    if (u._ep !== epN) {
      u._ep = epN;
      const c = P.factionCost(u.def);
      ep.cost += c;
      const a = u._arm || ep.arm;
      if (a) ep.share[a] = (ep.share[a] || 0) + c;
    }
    for (const wn of (u.def.weapons || [])) {
      const w = WEAPONS[wn];
      if (w && w.tgt && w.tgt.ground && w.range > reach) reach = w.range;
    }
  }
  /* the push's own centre from the first tick, never our own front door: a
     base-defence kill four seconds before the launch must not be billed to
     the wave that has not left yet */
  if (n) { ep.cx = sx / n; ep.cy = sy / n; }
  /* How far from the wave a kill may be credited: the wave's own deepest
     ground weapon plus four tiles, floored at twelve. A flat constant would
     under-credit precisely the posture that fights at twenty tiles, which is
     gunline - one arm measured on a shorter ruler than the others is a
     rigged comparison, and the previous design had exactly that. */
  ep.r = Math.max(12, reach + 4) * CFG.TILE;
}

/* Runs on the picture's own 0.8s clock rather than on think(), because
   liveTrack() is FIVE seconds (ai.js:1307) and a think at Veteran is 2.1: a
   kill has to be noticed while the track that saw it is still live. */
function learnWatch(now) {
  if (!learnOn()) return;
  bookEraWatch();
  if (!armNow) chooseArm();
  if (!ep) return;
  let n = 0, sx = 0, sy = 0;
  for (const u of attackWave) if (!u.dead) { sx += u.x; sy += u.y; n++; }
  if (n) { ep.cx = sx / n; ep.cy = sy / n; }
  /* Swept BEFORE the wave is declared over, using the last known centroid if
     it has just been wiped out: the final exchange of an annihilated wave is
     its most expensive one, and the previous design threw it away and then
     scored that wave as though it had killed nothing. */
  learnKills(now);
  if (!n || now - ep.t > (D.waveTime || 150) * 2) learnSettle();
}

/* ---- what we WATCHED die ----
   Four gates, and every one of them is our own eyes:
     r.t >= ep.t   we were still holding the track after this push began
     liveTrack(r)  this file's own five-second invariant (ai.js:1307) - the
                   same window trackedEntity() demands before anything here
                   is allowed to touch a record's `ref` at all. The previous
                   design used eight seconds and called it liveTrack's window,
                   which was simply untrue of the code it cited.
     staleness     the tile it was last seen on was overlooked by something
                   of ours within six seconds - the same six forgetStale()
                   uses to decide we have been back and looked.
     distance      it fell inside our own wave's own reach of our own wave.
   What this still cannot see is who fired the last shot: something killed
   beside our wave by an ally is credited to us, and something killed beside
   the player's army by ours is credited to the player. That is a bound, it
   is identical for all three postures so it cannot bias the ranking, and it
   is the same bound the human watching that fight is under. */
function learnKills(now) {
  const R2 = ep.r * ep.r;
  for (const r of seenU.values()) {
    if (r.scored || !r.ref || !r.ref.dead) continue;
    if (r.t < ep.t) continue;                  // we lost it before this push began
    if (!liveTrack(r)) continue;
    if (staleness((r.x / CFG.TILE) | 0, (r.y / CFG.TILE) | 0, now) > 6) continue;
    if (U.dist2(r.x, r.y, ep.cx, ep.cy) > R2) continue;
    r.scored = 1;
    ep.kills += r.cost || 300;
  }
}

/* A structure razed beside the wave. forgetStale() strikes a work off the
   plot ONLY when we have been back and looked at where it stood, so `gone`
   is itself the observation: there is nothing to add to it and nothing
   behind fog to read. Priced at worthOf(), the same valuation objectives()
   picks targets with, so the learner and the target picker agree about what
   a barracks is worth - and a defence is 40% of its cost there, which is
   what stops a wave farming sandbags for reward. THIS is the fatal the
   previous design shipped: it counted units only, so razing a base scored
   zero and every posture that wins by demolition looked worthless. */
function learnRazed(r) {
  if (!learnOn() || !ep) return;
  if (U.dist2(r.x, r.y, ep.cx, ep.cy) > ep.r * ep.r) return;
  ep.razed += worthOf(r.key);
}

/* ---- the only arithmetic that matters ----
   r is an exchange RATIO over the push's own committed cost, so a 4,700
   credit 1950s wave and a 15,000 credit 2020s wave are on one scale.
   A is that ratio MINUS the running mean of our own recent pushes, and the
   centring is the entire reason this design exists. Write

       r = mu(posture) + common + noise

   where `common` is everything true of the BATTLE rather than of the choice:
   the kills the fog hid, the casualties no list kept, the price level of the
   era, how good this opponent is, how defended this map is. `base` converges
   on the mean of r, which contains `common`; subtracting it deletes `common`
   exactly, for any size of it. Two postures therefore differ in their
   estimates by precisely the amount they differ in truth, and no shared bias
   can make them equal. The previous attempt compared r against an absolute
   and then clamped the result to the prior +- a bound, so a common offset of
   -0.8 pinned all four arms to the same boundary, the argmax tied, and the
   bandit picked the first arm in its list for twenty waves.

   CREDIT goes to what the push was MADE OF, not to what was chosen last.
   groundArmy() counts the marching wave, so while a wave is alive and
   winning the army is at strength and nothing is queued at all: the next
   wave is largely the same hulls, bought under an earlier posture. Each
   posture takes the cost share of the wave that it actually bought, and the
   posture that set the stance keeps at least a third whatever the factory
   managed to deliver - which is also what keeps its pull count moving, so no
   posture can sit unvisited with an exploration bonus growing for ever. */
function learnSettle() {
  const e = ep; ep = null;
  if (!e) return;
  /* A push too small to be a push proves nothing about a posture, and a flat
     zero written into a book is a claim that the posture is mediocre - which
     the book would then act on for the rest of the battle. */
  if (e.cost >= WAVE_MIN) {
    const r = U.clamp((e.kills + e.razed - e.lost) / e.cost, -1.2, 2.0);
    if (!baseN) { base = r; baseN = 1; }   // the first push sets the yardstick
    else {
      const A = r - base;
      base += (r - base) / Math.min(++baseN, BASE_N);
      const w = {};
      let tot = 0;
      for (const a of ARMS) { w[a] = e.share[a] || 0; tot += w[a]; }
      if (e.arm) {
        w[e.arm] = Math.max(w[e.arm], e.cost * MIN_CRED);
        tot = 0;
        for (const a of ARMS) tot += w[a];
      }
      if (tot > 0) for (const a of ARMS) {
        const s = w[a] / tot;
        if (s <= 0) continue;
        const b = book[a];
        b.n += s;
        /* a weighted running mean with a floored step: the step never falls
           below s/8, so eight fully credited pushes can re-shape an estimate
           however old it is. Nothing here is allowed to freeze. */
        b.q += (s / Math.min(b.n, NCAP)) * (A - b.q);
      }
    }
  }
  chooseArm();
}

/* what a probe or an overlay can see of all this, for the same reason `look`
   and `graves` are already exposed: so it can be measured rather than
   believed */
function learnState() {
  if (!book) return null;
  const out = { on: learnOn(), arm: armNow, base: base, waves: baseN, book: {} };
  for (const a of ARMS) out.book[a] = { n: book[a].n, q: book[a].q, p: book[a].p,
                                        ready: armReady(a) };
  if (ep) out.open = { cost: ep.cost, kills: ep.kills, razed: ep.razed,
                       lost: ep.lost, arm: ep.arm };
  return out;
}

/* ---- build toward a mixture instead of rolling for one ----

mineSigns = []; raidHeat = 0; raidT = 0; mineNext = 0;
/* the book is re-drawn from the manual for THIS army in THIS decade, the
   open push is closed and the yardstick thrown away: a restarted match
   must not score its first push against the previous battle's average or
   credit it to the previous battle's posture. */
bookInit();

seenVer++;
/* This is the exact moment the commander learns a structure is no
   longer there, and it learns it the only honest way: by going back
   and looking. So it is also the only place a razing can be credited
   to a push - see learnRazed(). Nothing here reads ref.dead, which
   would credit a building somebody else flattened inside our fog. */
if (r.gone) seenB.delete(id); else { r.gone = true; learnRazed(r); }

digest(now);
forgetStale(now);
/* On the picture's clock and not on think()'s: liveTrack() is five seconds
   (ai.js:1307) and a Veteran thinks every 2.1, so a kill has to be noticed
   while the track that saw it is still live rather than reconstructed
   afterwards off a stale memory. Immediately after forgetStale, so a work
   struck off this tick is credited to the push that took it. */
learnWatch(now);
pruneHypotheses();

